  grid-template-columns: 1fr 1fr 1fr 1fr;
  width: auto;
  padding: 0 24px;
}

.pricingTableHeader {
  color: #5b616e;
  text-align: center;
  border-bottom: 1px solid rgba(33, 207, 255, 0.21);
  padding: 24px 12px;
}

.pricingTableHeaderLeft {
  color: #ff4b0e;
  text-align: left;
  padding-top: 24px;
  padding-left: 0;
}

.subheadingLarge7 {
  color: #082753;
  letter-spacing: 0;
  -webkit-text-fill-color: inherit;
  background-image: none;
  background-clip: border-box;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 24px;
}

.subheadingLarge7TextColorBrandOrange {
  color: #019ae6;
  font-family: Roobert PRO, Arial, sans-serif;
  font-weight: 700;
}

.pricingHeaderLast {
  flex: none;
  justify-content: center;
  align-items: center;
  width: auto;
  height: auto;
  display: flex;
  position: relative;
}

.pricingTableCell {
  grid-column-gap: 4px;
  grid-row-gap: 4px;
  color: #5b616e;
  text-align: center;
  white-space: nowrap;
  word-break: keep-all;
  border-bottom: 1px solid rgba(33, 207, 255, 0.21);
  flex-direction: row;
  justify-content: center;
  align-items: center;
  padding: 24px 12px;
  display: flex;
}

.pricingTableCellLeft {
  grid-column-gap: 6px;
  grid-row-gap: 6px;
  color: #000;
  text-align: left;
  border-bottom-color: rgba(33, 207, 255, 0.21);
  justify-content: flex-start;
  align-items: center;
  padding-left: 0;
  position: relative;
}

.pricingTableCellNoBorder {
  border-bottom-style: none;
}

.paragraphRegular14 {
  color: #252525;
  letter-spacing: -0.02em;
  margin-bottom: 0;
  font-family: Roobert PRO, Arial, sans-serif;
  font-size: 16px;
  line-height: 28px;
}

/* Tooltip */
.tooltip {
  display: inline-block;
  position: relative;
  cursor: help;
}

.tooltipIco {
  width: 16px;
  height: 16px;
  opacity: 0.5;
}

@media screen and (max-width: 991px) {
  .pricingGrid {
    grid-template-columns: 1fr 1fr;
  }

  .pricingTable {
    width: 1200px;
  }

  .paragraphRegular14 {
    flex: 0 auto;
    width: 100%;
    display: block;
  }

  .pricingTableCell {
    min-width: auto;
  }

  .pricingTableCellLeft {
    width: auto;
    min-width: auto;
    max-width: none;
    overflow: visible;
  }

  .h3Heading3 {
    font-size: 23px;
  }
}

@media screen and (max-width: 767px) {
  .newPriceSec {
    margin-bottom: 0;
    padding-top: 72px;
    padding-bottom: 20px;
  }

  .pricingGrid {
    grid-template-columns: 1fr;
    padding-top: 5px;
    padding-bottom: 5px;
  }

  .pricingCard2,
  .pricingCard2WhiteCard {
    margin-top: 0;
  }

  .paragraphRegular14 {
    white-space: normal;
  }

  .pricingTable {
    width: 690px;
  }

  .pricingTabLink {
    min-width: 130px;
  }

  .h3Heading3 {
    font-size: 30px;
  }
}

@media screen and (max-width: 479px) {
  .pricingGrid {
    grid-template-columns: 1fr;
  }

  .pricingCard2,
  .pricingCard2WhiteCard {
    margin-top: 0;
  }

  .paragraphRegular14 {
    width: 100%;
  }

  .pricingTableCell {
    min-width: auto;
  }
}

